    /// <summary>
    /// Transfers Telegram Stars from the business account to the business bot; for bots only
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> TransferBusinessAccountStarsAsync(string businessConnectionId = default, long starCount = default)
    {

           using var activity =  StartCallActivity("TransferBusinessAccountStarsAsync", typeof(TransferBusinessAccountStars).FullName ?? "TransferBusinessAccountStarsAsync");

           try
           {
             return client.TransferBusinessAccountStarsAsync(businessConnectionId, starCount);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
